  rw_cells bsegs m (regb + O_REG_OWNER) [C8 (wz owner); C8 (wz first)] -> addressable m regb NEWSZ_REG -> 0 < regb -> regb + NEWSZ_REG <= aceil -> regb mod 16 = 0 ->
