  rw_cells bsegs m ioc [C8 (wz allocb); C8 (wz regb)] -> accessible m ioc 16 -> ioc mod 8 = 0 -> AIMG_TOP <= ioc -> ioc + 16 <= aceil ->
  (ioc + 16 <= regb \/ regb + NEWSZ_REG <= ioc) ->
